"""Direct quad density transitions in the original corridor parameter domain.

Every original path knot and both complete end rows are retained. Count changes
use existing 1:1/1:3/3:1 quad blocks, independently on each profile half. Integer
station/rank and crown identities join the charts before physical projection.
"""
import bpy
from . import curved_corridor_nodes as corridor
from . import boundary_quad_bridge_nodes as bridge
from .path_surface_nodes import _Nodes

c=corridor.c
MAX_SLABS=512


def even_stations(g,stations,enabled):
    """Add at most one midpoint; keep every original knot and endpoint exact.

    A slab's direct transition has an odd number of longitudinal boundary
    edges. An even slab count therefore supplies even inner-edge parity for
    conforming separator quads. Split the widest parameter gap, never remove
    a knot or loosen a geometry/size guard to obtain that parity.
    """
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);n=c._count(g,stations)
    x=g.separate(g.position())[0]
    next_x=g.separate(c._sample(g,stations,g.position(),g.math('MINIMUM',i+1.,n-1.),'FLOAT_VECTOR'))[0]
    gap=next_x-x;largest=c._stat(g,stations,gap,'Max')
    equal=g.node('ShaderNodeMath','Exact largest gap with first-index tie break');equal.operation='COMPARE'
    g.bind(gap,equal.inputs[0]);g.bind(largest,equal.inputs[1]);equal.inputs[2].default_value=0.
    selected=c._stat(g,stations,c.choose(g,equal.outputs[0],i,n),'Min')
    start=g.separate(c._sample(g,stations,g.position(),selected,'FLOAT_VECTOR'))[0]
    end=g.separate(c._sample(g,stations,g.position(),selected+1.,'FLOAT_VECTOR'))[0]
    needed=c.V(g,enabled)*g.math('MODULO',n-1.,2.)
    point=g.setpos(c._line(g,1),g.xyz(start+.5*(end-start)))
    point=c._store(g,point,'st_cs_budget',g.math('GREATER_THAN',end-start,0.),'BOOLEAN')
    order=g.node('GeometryNodeSortElements','Even separator-boundary parity with original stations retained');order.domain='POINT'
    g.bind(corridor.boundary._join(g,stations,point),order.inputs['Geometry']);g.bind(x,order.inputs['Sort Weight'])
    return c.choose(g,needed,order.outputs['Geometry'],stations,'GEOMETRY'),needed


def build():
    name='Prochitecture Streets / Original corridor density chart v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    g.socket('Path','NodeSocketGeometry')
    for key in ('Start','End','Width','Cell Size'):g.socket(key,'NodeSocketFloat')
    for key in ('Half','Start Intervals','End Intervals'):g.socket(key,'NodeSocketInt')
    g.socket('Input Valid','NodeSocketBool')
    g.socket('Even Side Intervals','NodeSocketBool',default=False)
    for key in ('Geometry','Stations','Diagnostics'):g.socket(key,'NodeSocketGeometry','OUTPUT')
    g.socket('Valid','NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');helper=_Nodes(g.g)
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    a,b,width,cell=[c.V(g,inp.outputs[key]) for key in ('Start','End','Width','Cell Size')]
    half=c.V(g,inp.outputs['Half']);bands=2.-g.math('ABSOLUTE',half)
    ca,cb=[c.V(g,inp.outputs[key])/bands for key in ('Start Intervals','End Intervals')]
    across=width/g.math('MAXIMUM',1.,bands);safe_cell=g.math('MAXIMUM',cell,.02)
    base=g.math('MAXIMUM',2.,2.*g.math('CEIL',across/(2.*safe_cell)))
    fa=g.math('MINIMUM',(b-a)/3.,g.math('MAXIMUM',width,2.*safe_cell*g.math('ABSOLUTE',ca-base)))
    fb=g.math('MINIMUM',(b-a)/3.,g.math('MAXIMUM',width,2.*safe_cell*g.math('ABSOLUTE',cb-base)))
    rate=g.math('MAXIMUM',g.math('ABSOLUTE',ca-base)/g.math('MAXIMUM',fa,1e-6),
                            g.math('ABSOLUTE',cb-base)/g.math('MAXIMUM',fb,1e-6))
    least=g.math('MINIMUM',base,g.math('MINIMUM',ca,cb))
    step=g.math('MINIMUM',g.math('MAXIMUM',width,4.*safe_cell),least/g.math('MAXIMUM',rate,1e-6))
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',b-a,1e-4)
    valid=valid*g.math('GREATER_THAN',width,1e-4)*g.math('GREATER_THAN',cell,.0199)
    valid=valid*g.math('LESS_THAN',g.math('ABSOLUTE',half),1.5)
    for n in (ca,cb):
        valid=valid*g.math('GREATER_THAN',n,1.5)*g.math('LESS_THAN',n,4096.5)
        valid=valid*g.math('COMPARE',g.math('MODULO',n,2.),0.)
    stations,nrows=corridor._stations(g,inp.outputs['Path'],c.choose(g,valid,a,0.),
                                    c.choose(g,valid,b,0.),g.math('MAXIMUM',step,.02))
    stations,parity_added=even_stations(g,stations,inp.outputs['Even Side Intervals'])
    nrows=c._count(g,stations)
    s=g.separate(g.position())[0]
    count=base+(ca-base)*c.bounded(g,1.-(s-a)/g.math('MAXIMUM',fa,1e-6))+\
               (cb-base)*c.bounded(g,1.-(b-s)/g.math('MAXIMUM',fb,1e-6))
    count=2.*g.math('CEIL',(count-1e-6)/2.)
    count=c.choose(g,g.math('LESS_THAN',i,.5),ca,
                   c.choose(g,g.math('GREATER_THAN',i,nrows-1.5),cb,count))
    stations=c._store(g,stations,'st_cr_count',count,'INT')
    valid=valid*g.math('LESS_THAN',nrows,MAX_SLABS+1.5)*c._stat(g,stations,c.named(g,'st_cs_budget','BOOLEAN'))
    ri=g.node('GeometryNodeRepeatInput','Keep source knots while reconciling corridor profile counts')
    ro=g.node('GeometryNodeRepeatOutput');ro.repeat_items.clear()
    ro.repeat_items.new('GEOMETRY','Geometry');ro.repeat_items.new('BOOLEAN','Valid')
    ri.pair_with_output(ro);ri.inputs['Valid'].default_value=True
    g.bind(c.choose(g,valid,(nrows-1.)*bands,0,'INT'),ri.inputs['Iterations'])
    at=c.V(g,ri.outputs['Iteration']);slab=g.math('FLOOR',at/bands);band=g.math('MODULO',at,bands)
    sa=g.separate(c._sample(g,stations,g.position(),slab,'FLOAT_VECTOR'))[0]
    sb=g.separate(c._sample(g,stations,g.position(),slab+1.,'FLOAT_VECTOR'))[0]
    na=c._read(g,stations,'st_cr_count',slab,'INT');nb=c._read(g,stations,'st_cr_count',slab+1.,'INT')
    left=g.setpos(c._line(g,na+1.),g.xyz(across*i/na,sa))
    right=g.setpos(c._line(g,nb+1.),g.xyz(across*i/nb,sb))
    call=g.node('GeometryNodeGroup','Direct count transition without triangulation')
    call.node_tree=bridge.build(exact_weld=True)
    for key,value in (('Boundary A',left),('Boundary B',right),('Cell Size',cell)):
        g.bind(value,call.inputs[key])
    call.inputs['Axis'].default_value=(1.,0.,0.)
    x,y,_=g.separate(g.position());u=(band+x/across)/bands
    side=c.named(g,'_bridge_source_side','INT');rank=c.named(g,'_bridge_source_index','INT')
    profile=g.math('GREATER_THAN',side,-.5);row=slab+side
    n=c.choose(g,g.math('LESS_THAN',side,.5),na,nb)
    station_key=g.xyz(0.,row,band*n+rank)
    old=c._vec(g,c.named(g,'_bridge_key','FLOAT_VECTOR'))
    layer=g.separate(c.named(g,'_bridge_key','FLOAT_VECTOR'))[2]
    crown=g.math('COMPARE',half,0.)*g.math('LESS_THAN',g.math('ABSOLUTE',u-.5),1e-6)
    crown_key=g.xyz(1.,slab,old[0]*8192.+layer)
    key=c.choose(g,profile,station_key,c.choose(g,crown,crown_key,g.xyz(2.,at,i),'VECTOR'),'VECTOR')
    mesh=call.outputs['Geometry']
    # Capture parameter coordinates before replacing the bridge key/positions.
    for name,value,kind in (('parameter',y,'FLOAT'),('u',u,'FLOAT'),
        ('end',c.choose(g,profile*g.math('LESS_THAN',row,.5),0,
                c.choose(g,profile*g.math('GREATER_THAN',row,nrows-1.5),1,-1,'INT'),'INT'),'INT'),
        ('rank',band*n+rank,'INT')):
        mesh=c._store(g,mesh,'st_cs_'+name,value,kind)
    mesh=c._store(g,mesh,'_cr_key',key,'FLOAT_VECTOR')
    mesh=g.setpos(mesh,g.xyz(width*c.named(g,'st_cs_u'),c.named(g,'st_cs_parameter')))
    g.bind(c.V(g,ri.outputs['Valid'])*c.V(g,call.outputs['Valid']),ro.inputs['Valid'])
    g.bind(corridor.boundary._join(g,ri.outputs['Geometry'],mesh),ro.inputs['Geometry'])
    mesh=c._store(g,ro.outputs['Geometry'],'_bridge_key',c.named(g,'_cr_key','FLOAT_VECTOR'),'FLOAT_VECTOR')
    welded,seams=bridge._weld(helper,mesh.s,exact_reference=True)
    good=valid*c.V(g,ro.outputs['Valid'])*c.V(g,seams)*c.V(g,bridge._mesh_good(helper,welded))
    diagnostics=c._line(g,1)
    for key,value,kind in (('valid',valid,'BOOLEAN'),('blocks_valid',ro.outputs['Valid'],'BOOLEAN'),
                          ('seams_valid',seams,'BOOLEAN'),('slabs',nrows-1.,'INT'),('base_count',base,'INT'),
                          ('parity_added',parity_added,'BOOLEAN')):
        diagnostics=c._store(g,diagnostics,'st_cr_'+key,value,kind)
    out=g.node('NodeGroupOutput')
    for key,value in (('Geometry',corridor.boundary._empty(g,welded,good)),('Stations',stations),
                      ('Diagnostics',diagnostics),('Valid',good)):g.bind(value,out.inputs[key])
    return g.g
